-- One-time backfill of stocks.sector / stocks.industry.
--
-- The static sector/industry lookup silently loaded 0 of 2,355 symbols
-- (UTF-8 BOM made csv.DictReader name the first column \ufeffsymbol), so
-- every stock outside the hand-curated SECTOR_MAP fell back to sector
-- 'Other' with industry NULL and vanished from the sector/industry
-- rankings. shared.py is fixed; this repairs the existing rows now
-- instead of waiting for a deploy + scan cycle.
--
-- Generated by scripts/gen_sector_industry_backfill.py
-- 2355 symbols: 2355 with a sector, 2355 with an industry (27 of them Sugar).
--
-- Sector is authoritative (curated SECTOR_MAP first, then the lookup CSV)
-- so it overwrites. Industry only overwrites where the value does not
-- depend on the live fundamentals scrape; elsewhere it fills NULLs and
-- leaves any live-scraped value alone. Symbols absent from both sources
-- are left untouched.

BEGIN;

CREATE TEMP TABLE _si (
  sym       text PRIMARY KEY,
  sector    text,
  industry  text,
  force_ind boolean NOT NULL
) ON COMMIT DROP;


UPDATE public.stocks s
SET sector   = COALESCE(v.sector, s.sector),
    industry = CASE WHEN v.force_ind THEN v.industry
                    ELSE COALESCE(s.industry, v.industry) END
FROM _si v
WHERE s.sym = v.sym;

COMMIT;

-- Verify: sector "Other" should drop from ~2,388 to a few hundred,
-- and Sugar should now exist as an industry.
SELECT count(*) FILTER (WHERE sector = 'Other')  AS sector_other,
       count(*) FILTER (WHERE industry IS NULL)  AS industry_null,
       count(*) FILTER (WHERE industry = 'Sugar') AS sugar,
       count(*)                                   AS total
FROM public.stocks;
